#include <bits/stdc++.h>
using namespace std;

int main() {
    string s((istreambuf_iterator<char>(cin)), istreambuf_iterator<char>());
    auto isVowel = [](char c) { return strchr("aeiouAEIOU", c) != nullptr; };
    int count = 0;
    size_t i = 0, n = s.size();
    while (i < n) {
        while (i < n && isspace((unsigned char)s[i])) i++;
        if (i >= n) break;
        size_t j = i;
        while (j < n && !isspace((unsigned char)s[j])) j++;
        // token s[i, j)
        bool ok = j - i >= 3, vowel = false, consonant = false;
        for (size_t k = i; k < j && ok; k++) {
            unsigned char c = s[k];
            if (c >= 128 || !isalnum(c)) ok = false;
            else if (isVowel(c)) vowel = true;
            else if (isalpha(c)) consonant = true;
        }
        if (ok && vowel && consonant) count++;
        i = j;
    }
    printf("%d\n", count);
}

import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        byte[] s = System.in.readAllBytes();
        int count = 0, i = 0, n = s.length;
        while (i < n) {
            while (i < n && isSpace(s[i])) i++;
            if (i >= n) break;
            int j = i;
            while (j < n && !isSpace(s[j])) j++;
            // token s[i, j)
            boolean ok = j - i >= 3, vowel = false, consonant = false;
            for (int k = i; k < j && ok; k++) {
                int c = s[k] & 0xFF;
                if ("aeiouAEIOU".indexOf(c) >= 0) vowel = true;
                else if (c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z') consonant = true;
                else if (c < '0' || c > '9') ok = false; // not an ASCII letter or digit
            }
            if (ok && vowel && consonant) count++;
            i = j;
        }
        System.out.println(count);
    }

    static boolean isSpace(byte c) {
        return c == ' ' || (c >= 9 && c <= 13);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strings"
)

func main() {
	data, _ := io.ReadAll(bufio.NewReader(os.Stdin))
	count := 0
	for _, w := range strings.Fields(string(data)) {
		ok, vowel, consonant := len(w) >= 3, false, false
		for i := 0; i < len(w) && ok; i++ {
			c := w[i]
			switch {
			case strings.IndexByte("aeiouAEIOU", c) >= 0:
				vowel = true
			case c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z':
				consonant = true
			case c >= '0' && c <= '9':
			default:
				ok = false // not an ASCII letter or digit
			}
		}
		if ok && vowel && consonant {
			count++
		}
	}
	fmt.Println(count)
}
